window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"uOApI6anaNg","speaker":"Moustafa Kamal Madbouly","role":"Prime Minister","country":"Egypt","region":"Middle East","url":"https://www.youtube.com/watch?v=uOApI6anaNg","date":"20260925","title":"🇪🇬 Egypt - Prime Minister Addresses United Nations General Debate, 81st Session | #UNGA","seconds":1216,"words":2569,"counts":{"claims":29,"promises":5,"attacks":2},"topics":[{"topic":"Israel-Gaza","share":0.1838,"seconds":223},{"topic":"UN reform","share":0.1226,"seconds":149},{"topic":"Regional security","share":0.1136,"seconds":138},{"topic":"AI governance","share":0.0745,"seconds":91},{"topic":"International law","share":0.0583,"seconds":71},{"topic":"Egypt water security","share":0.0579,"seconds":70},{"topic":"multilateralism","share":0.0552,"seconds":67},{"topic":"Global economy reform","share":0.0536,"seconds":65},{"topic":"Middle East nuclear","share":0.0522,"seconds":64},{"topic":"Sudan crisis","share":0.0519,"seconds":63},{"topic":"UNGA greetings","share":0.0509,"seconds":62},{"topic":"Climate action","share":0.0505,"seconds":61},{"topic":"AI strategy","share":0.0498,"seconds":61},{"topic":"Ceremony","share":0.0251,"seconds":31}],"timeline":[[5,66,"UNGA greetings"],[67,135,"multilateralism"],[136,207,"International law"],[208,287,"Israel-Gaza"],[288,364,"Israel-Gaza"],[365,433,"Israel-Gaza"],[435,506,"Regional security"],[507,574,"Regional security"],[574,645,"Egypt water security"],[646,709,"Sudan crisis"],[710,771,"UN reform"],[773,838,"Global economy reform"],[840,931,"AI governance"],[931,991,"AI strategy"],[993,1054,"Climate action"],[1056,1119,"Middle East nuclear"],[1120,1208,"UN reform"],[1209,1239,"Ceremony"]],"stances":{"UNGA greetings":"Moustafa Kamal Madbouly extends sincere congratulations to the President of the 81st session of the United Nations General Assembly.","multilateralism":"Moustafa Kamal Madbouly argues that the international community requires effective multilateralism rather than symbolic gestures to address the gap between proclaimed principles and actual implementation.","International law":"Moustafa Kamal Madbouly argues that restoring adherence to international law is urgent and requires three pillars of justice, while rejecting a complete rebuild of the system in favor of fulfilling its original purposes.","Israel-Gaza":"Moustafa Kamal Madbouly argues that the Palestinian issue is the clearest example of dysfunction in the international system and calls for a ceasefire, full compliance with peace plans, and immediate recovery efforts.","Regional security":"Egypt advocates for resolving crises through political solutions and state sovereignty rather than managing them, asserting that security is indivisible.","Egypt water security":"Moustafa Kamal Madbouly asserts that Egypt's water security is an existential issue that cannot be compromised and must be managed through cooperation rather than unilateral measures.","Sudan crisis":"Egypt supports Sudan's unity and institutions while asserting its own right to protect water security under international law.","UN reform":"Moustafa Kamal Madbouly argues that the current structure of the UN Security Council is outdated and lacks legitimacy because it does not fairly represent the world, and he calls for comprehensive reform based on African consensus documents.","Global economy reform":"Moustafa Kamal Madbouly argues that developing nations face disproportionate economic burdens and calls for urgent structural changes to the international financial system.","AI governance":"Moustafa Kamal Madbouly argues that artificial intelligence requires global governance frameworks to ensure it remains a public benefit rather than an exclusive privilege, while balancing innovation with responsibility.","AI strategy":"Egypt has launched a national AI strategy to ensure technology serves as a tool for development and reflects cultural diversity, while emphasizing that just transitions require fair implementation.","Climate action":"Moustafa Kamal Madbouly argues that climate action must be integrated with development and poverty reduction, emphasizing the need for implementation over diagnosis and calling for financing to reach vulnerable nations.","Middle East nuclear":"Moustafa Kamal Madbouly advocates for a Middle East free of nuclear weapons and emphasizes collective security through equal rules and prevention of escalation.","Ceremony":"Moustafa Kamal Madbouly expresses gratitude and well wishes before concluding his remarks."},"claims":[{"t":87,"quote":"Our world is changing at a pace far exceeding the ability of international governance institutions to respond.","topic":"multilateralism","kind":"fact"},{"t":95,"quote":"Our crisis does not lie in the absence of charters and principles, but rather in the widening gap between what we proclaim and what we implement","topic":"multilateralism","kind":"fact"},{"t":130,"quote":"confidence and the effectiveness of collective action and the multilateral system has declined.","topic":"multilateralism","kind":"fact"},{"t":147,"quote":"the countries of the global south, which comprise the overwhelming majority of the world's population, are among those most harmed by the decline of the rule of international law","topic":"International law","kind":"fact"},{"t":168,"quote":"Egypt, as a founding member of the United Nations, believes that restoring trust requires three interconnected pillars: justice and representation and decision-making, justice and the application of the law, and justice and the distribution of development and social transformation","topic":"International law","kind":"self_credit"},{"t":241,"quote":"What the Palestinian people have endured and continue to endure in terms of suffering, repression, and violations must not become a normalized reality or a protracted crisis managed managed from one cycle to the other.","topic":"Israel-Gaza","kind":"fact"},{"t":257,"quote":"Securing the ceasefire in the Gaza Strip in accordance with the President Trump's and the Sharm El Sheikh summit peace plan, ensuring full compliance with it, ending daily Israeli violations, completing the the withdrawal, guaranteeing the safe and sustainable delivery of humanitarian aid, enabling the national committee for the administration of Gaza to carry out its duties, and then moving immediately toward early recovery and reconstruction, these are not merely humanitarian steps.","topic":"Israel-Gaza","kind":"fact"},{"t":344,"quote":"The goal remains unequivocally clear, the establishment of an independent, sovereign, and territorially contiguous Palestinian states state on the lines of the 4th of June, 1967 with East Jerusalem as its capital within the framework of the two-state solution and in accordance with international legitimacy resolutions.","topic":"Israel-Gaza","kind":"fact"},{"t":406,"quote":"It has been the largest provider of humanitarian assistance reaching the Gaza Strip.","topic":"Israel-Gaza","kind":"fact"},{"t":438,"quote":"managing crisis rather than resolving them does not create stability. Rather, it postpones the explosion and increases its costs.","topic":"Regional security","kind":"fact"},{"t":480,"quote":"the capable national state that embraces all its citizens and legitimate institutions remain the only true foundation for stability.","topic":"Regional security","kind":"fact"},{"t":507,"quote":"Likewise, any regional actor that believes that its political or economic interests can be achieved achieved by undermining national state institutions, supporting militias, or promoting separatist agendas and civil conflict, clearly becomes part of the problem.","topic":"Regional security","kind":"fact"},{"t":526,"quote":"Confronting such actors and their practices becomes the responsibility of the international community as a whole.","topic":"Regional security","kind":"fact"},{"t":588,"quote":"Egypt's water security is an existential issue that is not open to compromise.","topic":"Egypt water security","kind":"fact"},{"t":594,"quote":"The Nile is not merely an economic resource. It is the lifeline upon which the existence and development of Egyptian society have depended throughout history.","topic":"Egypt water security","kind":"fact"},{"t":659,"quote":"In this regard, Egypt preserves reserves its legitimate and internationally recognized right under the under the charter of the United Nations and international law to protect its water security and preserve the existential resources of its people.","topic":"Sudan crisis","kind":"fact"},{"t":676,"quote":"Amid the multiple threats facing our we recall the crisis of brotherly Sudan, a crisis whose consequences extend beyond military confrontations to affect the security and safety of civilians and threaten to dismantle the state institutions.","topic":"Sudan crisis","kind":"fact"},{"t":725,"quote":"More than eight decades have passed since the founding of the United Nations.","topic":"UN reform","kind":"fact"},{"t":741,"quote":"Institutions that were created for a different world cannot maintain full legitimacy and effectiveness if they do not reflect the world they are meant to serve today and represent the concerns and interests of the majority of its population.","topic":"UN reform","kind":"fact"},{"t":780,"quote":"Developing countries are required to accelerate development, create jobs, finance green transitions, and adapt to crises, while simultaneously facing growing debt burdens, higher financing costs, and a shrinking fiscal space.","topic":"Global economy reform","kind":"fact"},{"t":879,"quote":"Artificial intelligence opens boundless horizons for growth, knowledge, innovation, and improved services.","topic":"AI governance","kind":"fact"},{"t":886,"quote":"Yet, it may also create a vast new divide in power linked to computing capacity, data, models, skills, and financing.","topic":"AI governance","kind":"fact"},{"t":965,"quote":"Egypt has launched the second edition of its national artificial intelligence strategy 2025-2030","topic":"AI strategy","kind":"fact"},{"t":1012,"quote":"Drawing on Egypt's experience and hosting the climate conference in Sharm El Sheikh and the decision it adopted","topic":"Climate action","kind":"fact"},{"t":1020,"quote":"the gap no longer lies in diagnosing the problem, but in implementation","topic":"Climate action","kind":"fact"},{"t":1056,"quote":"And its commitment to the goal of establishing a Middle East free of nuclear weapons and all other weapons of mass destruction.","topic":"Middle East nuclear","kind":"fact"},{"t":1095,"quote":"Drawing upon its Arab, African, and Mediterra- Mediterranean heritage, its historic role in founding the multilateral international order, and its principled commitment to its survival and sustainability","topic":"Middle East nuclear","kind":"self_credit"},{"t":1135,"quote":"Legitimacy gains meaning when it produces results. Institutions regain trust when they do justice to those they serve.","topic":"UN reform","kind":"fact"},{"t":1143,"quote":"Trust is not demanded, it is built through justice. Transformation is not imposed, it is managed through participation.","topic":"UN reform","kind":"fact"}],"promises":[{"t":413,"quote":"Egypt will continue to work toward reconstruction and opening a viable political horizon.","topic":"Israel-Gaza","kind":"promise"},{"t":1046,"quote":"Therefore, Egypt reaffirms its commitment to a balanced system of disarmament and non-proliferation free from double standards","topic":"Climate action","kind":"promise"},{"t":1108,"quote":"Egypt will remain a bridge for cooperation and a partner to all those who seek a more just and effective international system.","topic":"Middle East nuclear","kind":"promise"},{"t":1117,"quote":"We will continue investing in partnerships with all parties.","topic":"Middle East nuclear","kind":"promise"},{"t":1151,"quote":"Egypt will continue to support every effort that restores trust and effectiveness to our multilateral international system","topic":"UN reform","kind":"promise"}],"attacks":[{"t":315,"quote":"systematic Israeli violations of international law","topic":"Israel-Gaza","target":"Israel"},{"t":508,"quote":"any regional actor that believes that its political or economic interests can be achieved achieved by undermining national state institutions, supporting militias, or promoting separatist agendas and civil conflict","topic":"Regional security","target":"Unnamed opponents"}],"greece":[],"said":[],"pickup":[],"transcript":[{"t":5,"topic":"UNGA greetings","text":"The Assembly will now listen to a statement delivered by His Excellency Dr. Mostafa Kamal Madbouly, Prime Minister of the Arab Republic of Egypt. I request protocol to escort His Excellency and invite him to address the In the name of God, the merciful, the compassionate. Mr. Khali Rahman, President of the 81st session of the United Nations General Assembly, Mr. Antonio Guterres, Secretary General of the United Nations, Your Majesties, Excellencies, and Highnesses, heads of state and government, ladies and gentlemen, at the outset, I am pleased to extend my sincere congratulations to His Excellency Khali Rahman on assuming the presidency of the current session of the General Assembly."},{"t":67,"topic":"multilateralism","text":"We assure him of our full support and confidence in his ability to successfully steer the work of the session. This year, the General Assembly convenes under a theme that accurately reflects the challenge facing the international restoring trust and managing Our world is changing at a pace far exceeding the ability of international governance institutions to respond. Our crisis does not lie in the absence of charters and principles, but rather in the widening gap between what we proclaim and what we implement, and between those who make decisions and those who are affected by them. Our world does not need a merely symbolic multilateralism that brings together states in open discussions. Rather, it needs effective multilateralism in which every state has a voice and every people receive a fair share of decisions, opportunities, and It is no exaggeration to say that confidence and the effectiveness of collective action and the multilateral system has declined."},{"t":136,"topic":"International law","text":"There's an urgent need to restore adherence to international law, to avoid policies based on power polarization and double It is no coincidence that the countries of the global south, which comprise the overwhelming majority of the world's population, are among those most harmed by the decline of the rule of international law, the weakening role of international organizations, and the fragility of global governance and international cooperation frameworks. From this perspective, Egypt, as a founding member of the United Nations, believes that restoring trust requires three interconnected pillars: justice and representation and decision-making, justice and the application of the law, and justice and the distribution of development and social transformation This is not a call to rebuild the international system from scratch. It is a call to fulfill its original promises and purposes, notably sovereign equality among states, respect for law, peaceful settlement of disputes, international cooperation for the benefit of peoples, and enabling them to reap the benefits of accelerating scientific progress."},{"t":208,"topic":"Israel-Gaza","text":"The multilateral international system remains an indispensable choice. However, its survival depends on strengthening justice and ensuring the effectiveness and sustainability of its institutions, instead of merely repeating the principles for which it was established without making meaningful action. Mr. President, if justice and the application of rules is the litmus test of the credibility of the international system, then the Palestinian issue remains the clearest example of the existing dysfunction. What the Palestinian people have endured and continue to endure in terms of suffering, repression, and violations must not become a normalized reality or a protracted crisis managed managed from one cycle to the other. Securing the ceasefire in the Gaza Strip in accordance with the President Trump's and the Sharm El Sheikh summit peace plan, ensuring full compliance with it, ending daily Israeli violations, completing the the withdrawal, guaranteeing the safe and sustainable delivery of humanitarian aid, enabling the national committee for the administration of Gaza to carry out its duties, and then moving immediately toward early recovery and reconstruction, these are not merely humanitarian steps."},{"t":288,"topic":"Israel-Gaza","text":"They are also the essential gateway to a serious political process that addresses the root causes of the conflict and resolves them. In this context, Egypt reaffirms its categorical rejection of any attempt to displace the Palestinian people from their land, whether from the Gaza Strip or from the West Bank, including East The international community as a whole bears a clear responsibility to stop systematic Israeli violations of international law. Peace cannot be built on uprooting a people from their land. Believing that stability can be achieved in the region while ignoring the suffering of the Palestinian people and merely managing the occupation rather than ending it is nothing but illusion. The goal remains unequivocally clear, the establishment of an independent, sovereign, and territorially contiguous Palestinian states state on the lines of the 4th of June, 1967 with East Jerusalem as its capital within the framework of the two-state solution and in accordance with international legitimacy resolutions."},{"t":365,"topic":"Israel-Gaza","text":"This requires preserving the unity of the Palestinian territory and the Palestinian political system, enabling the Palestinian people to manage their own affairs and build their state and ensuring that the international community fulfills its responsibility to protect civilians, reject collective collective punishment, and guarantee respect for international humanitarian law. It also requires recognizing Palestinian rights as inalienable rights, not as bargaining chips to be granted or withheld according to power balances, political posturing, or electoral calculations. Egypt has shouldered its responsibility alongside its partners to secure the It has been the largest provider of humanitarian assistance reaching the Gaza Strip. Egypt will continue to work toward reconstruction and opening a viable political horizon. However, the success of these efforts hinges on an international will capable of transforming legitimacy into decisive international action that moves from managing the tragic the tragedy to ending its causes."},{"t":435,"topic":"Regional security","text":"Mr. President, the experience of our region confirms that managing crisis rather than resolving them does not create stability. Rather, it postpones the explosion and increases its costs. Accordingly, Egypt Egypt remains committed to a clear vision for regional security based on state sovereignty, territorial integrity, respect for national institutions, rejection of the dismantling of states or the the of parallel entities, and prioritizing political solutions and inclusive national settlements over the logic of force and the imposition of effect a In every crisis across the broader Middle East from the Atlantic Ocean to the Gulf, circumstances and details may differ, but the capable national state that embraces all its citizens and legitimate institutions remain the only true foundation for stability. Security is indivisible. The security of one state cannot be built upon the insecurity of its neighbors, or upon threats to shipping, trade, and energy routes, or violations of state sovereignty through attacks carried out in violation of international law."},{"t":507,"topic":"Regional security","text":"Likewise, any regional actor that believes that its political or economic interests can be achieved achieved by undermining national state institutions, supporting militias, or promoting separatist agendas and civil conflict, clearly becomes part of the problem. Confronting such actors and their practices becomes the responsibility of the international community as a whole. regional crises cannot be treated as isolated cases. They must be viewed within an interconnected regional security environment that supports the state's institutions, unity, and sovereignty. That encourages political settlements and be peace building based on the principle of national and regional ownership of solutions. Ending external interferences and preventing crises from turning into arenas for regional and international competition over the resources and capabilities of the peoples of the region."},{"t":574,"topic":"Egypt water security","text":"The protection of states and their sovereignty is inseparable from protecting the resources upon which people's livelihoods depend. In this context, I wish to state clearly and un- that Egypt's water security is an existential issue that is not open to compromise. The Nile is not merely an economic resource. It is the lifeline upon which the existence and development of Egyptian society have depended throughout history. Egypt believes that trans- transboundary water resources should be a field for cooperation and integration, not conflict. We also believe that water security and development are not contradictory objectives, but complementary ones when political will exists, when intentions are sincere, and when international law is respected. We do not oppose the right of any people to development. Rather, we defend a clear and just principle that the development of one party must not be built upon causing harm to Shared resources cannot be managed through unilateral measures or fait accompli policies."},{"t":646,"topic":"Sudan crisis","text":"They must be managed through cooperation, good neighborliness, and the conclusion of binding agreements in accordance with international law that preserve the legitimate rights and interests of all parties. In this regard, Egypt preserves reserves its legitimate and internationally recognized right under the under the charter of the United Nations and international law to protect its water security and preserve the existential resources of its people. Amid the multiple threats facing our we recall the crisis of brotherly Sudan, a crisis whose consequences extend beyond military confrontations to affect the security and safety of civilians and threaten to dismantle the state institutions. In confronting these threats and dangers, the Sudan has in Egypt a strong supporter of its people and the right to unity, to institutions capable of safeguarding their resources, and to a justice that upholds their dignity."},{"t":710,"topic":"UN reform","text":"Mr. President, justice in rules is not complete if the institutions that make decisions do not fairly represent the world they More than eight decades have passed since the founding of the United Nations. Yet, the structure of the international system's institutions, particularly the Security Council, still reflect historical balances that have become outdated. Institutions that were created for a different world cannot maintain full legitimacy and effectiveness if they do not reflect the world they are meant to serve today and represent the concerns and interests of the majority of its population. In this context, Egypt continues to advocate genuine and comprehensive reform of the Security Council, in accordance with the Ezulwini Consensus and the Sirte Declaration, particularly to mend the historical injustice suffered by Africa."},{"t":773,"topic":"Global economy reform","text":"The imbalance in political representation is matched by another imbalance in the global economy. Developing countries are required to accelerate development, create jobs, finance green transitions, and adapt to crises, while simultaneously facing growing debt burdens, higher financing costs, and a shrinking fiscal space. Therefore, reforming international financial architecture is no longer a luxury, but a necessity. We need financial institutions that are more representative and responsive. We need expanded concessional financing, greater mobilization and lending capacities for multilateral development banks, and accelerated debt workout in a fair and effective manner. We need innovative financing tools and a fairer system for assessing countries' needs and investment risks, thus enabling the mobilization of private capital without shifting risks onto the most vulnerable countries."},{"t":840,"topic":"AI governance","text":"Countries should not be forced to choose between debt servicing and financing education, health care, food security, and essential infrastructure. Development is not charity. It is a right and a shared interest. Investing in development is an investment in global stability and in the ability of states to prevent crises before they become cross-border humanitarian and security crises. Mr. President, as we work to correct the imbalances inherited from the last century, we must not allow them to be reproduced in the future. Artificial intelligence opens boundless horizons for growth, knowledge, innovation, and improved services. Yet, it may also create a vast new divide in power linked to computing capacity, data, models, skills, and financing. managing this transformation requires the establishment of governance frameworks for artificial intelligence and emerging technologies on the basis that technology is a global public benefit and not an exclusive privilege enjoyed by a limited number of states or It supports the role of the United Nations and a a dialogue to develop principles that balance innovation and responsibility, protect privacy, guarantee transparency, accountability, non-discrimination, human"},{"t":931,"topic":"AI strategy","text":"oversight, respect for international law, technology and knowledge transfer, financing of digital infrastructure and skills development. This would enable developing countries to become producers and developers of technology rather than merely being markets for its consumption. Artificial intelligence should also reflect the linguistic and cultural diversity of the Arab and African languages and communities should receive fair representation in data and models. Egypt has launched the second edition of its national artificial intelligence strategy 2025-2030, grounded in its firm conviction that the safe and responsible use of technology and the development of national capacities are inseparable requirements. The same principle governs the green transition. There can be no just transition if ambition is dissociated from fair implementation."},{"t":993,"topic":"Climate action","text":"Climate action must go hand-in-hand with development, poverty reduction, and job creation. Adaptation, water security, and food security must receive the priority they deserve, especially in Africa and the countries most vulnerable to the impacts of climate change. Drawing on Egypt's experience and hosting the climate conference in Sharm El Sheikh and the decision it adopted, we can affirm that the gap no longer lies in diagnosing the problem, but in implementation, especially in translating commitments into financing flows, projects, and technologies that reach the countries and communities most in need. In a world where geopolitical and technological transformations are accelerating, this must not lead us into more dangerous arms races. Therefore, Egypt reaffirms its commitment to a balanced system of disarmament and non-proliferation free from double standards."},{"t":1056,"topic":"Middle East nuclear","text":"And its commitment to the goal of establishing a Middle East free of nuclear weapons and all other weapons of mass destruction. Collective security is not achieved through the accumulation of instruments of destruction. Rather, it is achieved through equal rules, obligations applicable to all, and a political will that prioritizes the prevention of escalation rather than having a delayed reaction after crisis occur. Mr. President, as Egypt presents this vision, it is not merely calling for a reform of the international system. Egypt is putting its experience and capabilities in service of solutions. Drawing upon its Arab, African, and Mediterra- Mediterranean heritage, its historic role in founding the multilateral international order, and its principled commitment to its survival and sustainability, Egypt will remain a bridge for cooperation and a partner to all those who seek a more just and effective international system. We will continue investing in partnerships with all parties."},{"t":1120,"topic":"UN reform","text":"We remain open to cooperation and exchange of expertise and working with all nations in both the global north and the global south on solutions that do not impose a single model, but respect national priorities and are based on shared ownership. Legitimacy gains meaning when it produces results. Institutions regain trust when they do justice to those they serve. Trust is not demanded, it is built through justice. Transformation is not imposed, it is managed through participation. Egypt will continue to support every effort that restores trust and effectiveness to our multilateral international system and contributes to managing the transformations of our rapidly changing world in a fair and participatory manner serving the interests of our peoples and future Before concluding, I wish to take this opportunity from this rostrum to extend our sincere thanks and appreciation to Mr. Antonio Guterres, Secretary-General of the United Nations, who has led the organization through one of the most difficult and critical periods in its history with courage, and a a sincere commitment to fulfilling his mandate to protect international law, preserve the standing and role of the United Nations, maintain its credibility and moral authority, and defend the principles upon which the organization was founded."},{"t":1209,"topic":"Ceremony","text":"These efforts will remain appreciated and remembered. As I express our profound gratitude for all that he has done, I wish him every in his future endeavors. Thank you for your attention. &gt;&gt; On behalf of the General Assembly, I thank His Excellency the Prime Minister of Egypt."}],"compare":[{"topic":"Israel–Palestine","share":0.1989,"mean":0.0516,"rank":10,"others":76},{"topic":"Artificial Intelligence","share":0.1345,"mean":0.05,"rank":24,"others":83},{"topic":"UN & its reform","share":0.1326,"mean":0.2051,"rank":127,"others":170},{"topic":"Regional Security","share":0.123,"mean":0.004,"rank":2,"others":12},{"topic":"International Law & Order","share":0.1229,"mean":0.0601,"rank":36,"others":102},{"topic":"Water Access","share":0.0626,"mean":0.0032,"rank":5,"others":7},{"topic":"Global Economy","share":0.0581,"mean":0.0143,"rank":25,"others":31},{"topic":"Middle East","share":0.0565,"mean":0.0071,"rank":11,"others":19}]};
